// Android build defaults for this reference host. `android/` is regenerated by
// `expo prebuild`, so the settings live here instead of in gradle.properties.
const { withGradleProperties } = require('expo/config-plugins');

const properties = {
  // Physical arm64 devices only; pass -PreactNativeArchitectures=x86_64 for an emulator.
  reactNativeArchitectures: 'arm64-v8a',
  // Reuse task outputs across builds and give the daemon room for native compilation.
  'org.gradle.caching': 'true',
  'org.gradle.jvmargs': '-Xmx4g -XX:MaxMetaspaceSize=1g -XX:+HeapDumpOnOutOfMemoryError',
  // PNG crunching only shrinks assets; skip it for faster release builds.
  'android.enablePngCrunchInReleaseBuilds': 'false',
};

module.exports = function withAndroidBuildPerformance(config) {
  return withGradleProperties(config, (gradle) => {
    for (const [key, value] of Object.entries(properties)) {
      const existing = gradle.modResults.find(
        (item) => item.type === 'property' && item.key === key
      );
      if (existing) existing.value = value;
      else gradle.modResults.push({ type: 'property', key, value });
    }
    return gradle;
  });
};
